import java.util.*;public class QueueRedesignBenchmark{static long run(Queue<Integer>q,int n){long s=System.nanoTime();for(int i=0;i<n;i++)q.offer(i);while(!q.isEmpty())q.poll();return System.nanoTime()-s;}public static void main(String[]x){int n=x.length==0?100000:Integer.parseInt(x[0]);for(int i=1;i<=5;i++){System.out.println("repeat "+i+" LinkedList ns="+run(new LinkedList<>(),n));System.out.println("repeat "+i+" ArrayDeque ns="+run(new ArrayDeque<>(),n));}}}